+using System.ClientModel;
+using System.ComponentModel;
+using Microsoft.Extensions.AI;
+using OpenAI;
+
+// --- Configuration ---
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
+var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
+
+Console.WriteLine("=== Research Agent ===");
+Console.Write("Enter a topic to research: ");
+var topic = Console.ReadLine()?.Trim();
+if (string.IsNullOrWhiteSpace(topic))
+{
+    Console.WriteLine("No topic provided. Exiting.");
+    return;
+}
+
+// --- Tools ---
+var researchNotes = new ResearchNotes();
+
+var searchTool = AIFunctionFactory.Create(
+    (string query) =>
+    {
+        Console.WriteLine($"  [Searching] \"{query}\"");
+        return WebSearch.SearchAsync(query);
+    },
+    "web_search",
+    "Searches the web for a query and returns a list of results with titles, URLs, and snippets.");
+
+var addNoteTool = AIFunctionFactory.Create(
+    ([Description("A concise note capturing a key finding")] string note,
+     [Description("The source URL for the finding")] string source) =>
+    {
+        researchNotes.Add(note, source);
+        Console.WriteLine($"  [Note added] {note[..Math.Min(note.Length, 60)]}...");
+        return "Note saved successfully.";
+    },
+    "take_note",
+    "Saves a research note with its source for later summarization.");
+
+var getNotesTool = AIFunctionFactory.Create(
+    () => researchNotes.GetAll(),
+    "get_notes",
+    "Retrieves all research notes taken so far.");
+
+// --- Build the AI client with tools ---
+IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
+    .GetChatClient(model)
+    .AsIChatClient()
+    .AsBuilder()
+    .UseFunctionInvocation()
+    .Build();
+
+var chatOptions = new ChatOptions
+{
+    Tools = [searchTool, addNoteTool, getNotesTool],
+    Temperature = 0.3f
+};
+
+// --- Agent loop ---
+var messages = new List<ChatMessage>
+{
+    new(ChatRole.System, """
+        You are a research agent. Your goal is to thoroughly research the given topic
+        using the web_search tool, take notes on key findings using the take_note tool,
+        and then provide a comprehensive summary.
+
+        Strategy:
+        1. Search for the topic from multiple angles (general overview, recent developments, key facts).
+        2. Take notes on the most important findings, always including the source URL.
+        3. After gathering enough information (at least 3-5 searches), retrieve your notes and write
+           a well-structured summary with citations.
+
+        Be thorough but efficient. Aim for 3-5 searches to cover the topic well.
+        """),
+    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
+};
+
+Console.WriteLine($"\nResearching \"{topic}\"...\n");
+
+var response = await client.GetResponseAsync(messages, chatOptions);
+
+Console.WriteLine("\n=== Research Summary ===\n");
+Console.WriteLine(response.Text);
+Console.WriteLine($"\n=== Research complete. {researchNotes.Count} notes collected. ===");
+
+// --- Supporting types ---
+
+public class ResearchNotes
+{
+    private readonly List<(string Note, string Source, DateTime Timestamp)> _notes = [];
+
+    public int Count => _notes.Count;
+
+    public void Add(string note, string source)
+    {
+        _notes.Add((note, source, DateTime.UtcNow));
+    }
+
+    public string GetAll()
+    {
+        if (_notes.Count == 0) return "No notes taken yet.";
+
+        return string.Join("\n\n", _notes.Select((n, i) =>
+            $"[{i + 1}] {n.Note}\n    Source: {n.Source}"));
+    }
+}
+
+public static class WebSearch
+{
+    private static readonly HttpClient Http = new();
+
+    public static async Task<string> SearchAsync(string query)
+    {
+        // Uses the free DuckDuckGo HTML endpoint for search results
+        var encoded = Uri.EscapeDataString(query);
+        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
+
+        try
+        {
+            using var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
+            var response = await Http.SendAsync(request);
+            var html = await response.Content.ReadAsStringAsync();
+
+            // Parse results from DDG HTML response
+            var results = ParseDuckDuckGoResults(html);
+            return results.Length > 0
+                ? string.Join("\n\n", results.Take(5))
+                : "No results found.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}";
+        }
+    }
+
+    private static string[] ParseDuckDuckGoResults(string html)
+    {
+        var results = new List<string>();
+        var snippetTag = "class=\"result__snippet\"";
+        var titleTag = "class=\"result__a\"";
+
+        var position = 0;
+        while (results.Count < 5)
+        {
+            var titleStart = html.IndexOf(titleTag, position, StringComparison.Ordinal);
+            if (titleStart < 0) break;
+
+            var title = ExtractTagContent(html, titleStart);
+            var href = ExtractHref(html, titleStart);
+
+            var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
+            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";
+
+            if (!string.IsNullOrWhiteSpace(title))
+            {
+                results.Add($"Title: {title}\nURL: {href}\nSnippet: {snippet}");
+            }
+
+            position = titleStart + 1;
+        }
+
+        return results.ToArray();
+    }
+
+    private static string ExtractTagContent(string html, int classAttrPos)
+    {
+        var tagClose = html.IndexOf('>', classAttrPos);
+        if (tagClose < 0) return "";
+        var contentStart = tagClose + 1;
+        var contentEnd = html.IndexOf('<', contentStart);
+        if (contentEnd < 0) return "";
+        return System.Net.WebUtility.HtmlDecode(html[contentStart..contentEnd]).Trim();
+    }
+
+    private static string ExtractHref(string html, int nearPos)
+    {
+        // Look backwards for href
+        var searchStart = Math.Max(0, nearPos - 500);
+        var segment = html[searchStart..nearPos];
+        var hrefIdx = segment.LastIndexOf("href=\"", StringComparison.Ordinal);
+        if (hrefIdx < 0) return "";
+        var urlStart = hrefIdx + 6;
+        var urlEnd = segment.IndexOf('"', urlStart);
+        if (urlEnd < 0) return "";
+        var rawUrl = segment[urlStart..urlEnd];
+        // DDG wraps URLs in a redirect; extract the actual URL
+        if (rawUrl.Contains("uddg="))
+        {
+            var param = rawUrl[(rawUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5)..];
+            var ampIdx = param.IndexOf('&');
+            if (ampIdx > 0) param = param[..ampIdx];
+            return Uri.UnescapeDataString(param);
+        }
+        return rawUrl;
+    }
+}

